export interface FieldOption {
  value: string;
  label: string;
}

export interface LoadOptionsContext {
  // Decrypted credential of the node, null when the node has none.
  credential: Record<string, unknown> | null;
}

// One field of a node's form.
export interface NodeProperty {
  name: string;
  displayName: string;
  type: 'string' | 'number' | 'boolean' | 'options' | 'collection';
  required?: boolean;
  default?: unknown;
  description?: string;
  placeholder?: string;
  // Takes {{ }} expressions, resolved per item before the node runs.
  expression?: boolean;
  multiline?: boolean;
