import { Injectable } from '@nestjs/common';
import { PrismaService } from '@app/database';
import { EncryptionUtil } from '@app/shared/utils/encryption.util';

const UUID_PATTERN =
  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

export interface StoredCredential {
  id: string;
  ownerId: string;
  name: string;
  connectorKey: string;
  secret: <REDACTED>, unknown>;
}

// Decrypted credentials for code that runs on the user's behalf (activation,
// webhooks, OAuth2, dynamic options). Secrets never leave the server.
@Injectable()
export class CredentialVault {
  constructor(private readonly prisma: PrismaService) {}

  // The credential if it exists and belongs to `ownerId`, else null.
  async findOwned(
    credentialId: unknown,
    ownerId: string,
  ): Promise<StoredCredential | null> {
    const credential = await this.find(credentialId);
    return credential?.ownerId === ownerId ? credential : null;
  }

  async find(credentialId: unknown): Promise<StoredCredential | null> {
    // The column is a UUID: anything else would make the query itself fail.
    if (typeof credentialId !== 'string' || !UUID_PATTERN.test(credentialId)) {
      return null;
    }
    const row = await this.prisma.connectorCredential.findUnique({
      where: { id: credentialId },
      include: { connector: { select: { key: true } } },
    });
    if (!row) return null;
    return {
      id: row.id,
      ownerId: row.ownerId,
      name: row.name,
      connectorKey: row.connector.key,
      secret: <REDACTED>
        EncryptionUtil.decrypt(row.encryptedSecret, encryptionKey()),
      ) as Record<string, unknown>,
    };
  }

  async updateSecret(
    credentialId: string,
    secret: <REDACTED>, unknown>,
  ): Promise<void> {
    await this.prisma.connectorCredential.update({
      where: { id: credentialId },
      data: {
        encryptedSecret: <REDACTED>
          JSON.stringify(secret),
          encryptionKey(),
        ),
      },
    });
  }
}

function encryptionKey(): string {
  const key = process.env['ENCRYPTION_KEY'];
  if (!key) throw new Error('Credential encryption key is not configured');
  return key;
}
import { useCallback, useEffect, useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { errorMessage, triggerService } from '../services/trigger.service';
import { credentialKeys } from './useCredentials';

interface CallbackMessage {
  type?: unknown;
  status?: unknown;
  credentialId?: unknown;
  message?: unknown;
}

// Connects an OAuth2 credential in a pop-up. The callback page posts
// { type: 'oauth2-callback', status, credentialId | message } and closes.
export function useOAuth2Popup(onConnected?: (credentialId: string) => void) {
  const queryClient = useQueryClient();
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const waitingFor = useRef<string | null>(null);

  useEffect(() => {
    const handle = (event: MessageEvent<CallbackMessage>) => {
      if (event.data?.type !== 'oauth2-callback' || !waitingFor.current) return;
      waitingFor.current = null;
      setPending(false);
      if (event.data.status === 'success' && typeof event.data.credentialId === 'string') {
        setError(null);
        void queryClient.invalidateQueries({ queryKey: credentialKeys.all });
        void queryClient.invalidateQueries({ queryKey: ['node-options'] });
        onConnected?.(event.data.credentialId);
      } else {
        setError(typeof event.data.message === 'string' ? event.data.message : 'Sign-in failed');
      }
    };
    window.addEventListener('message', handle);
    return () => window.removeEventListener('message', handle);
  }, [onConnected, queryClient]);

  const connect = useCallback(async (credentialId: string) => {
    setError(null);
    setPending(true);
    waitingFor.current = credentialId;
    // Opened before the request so pop-up blockers allow it.
    const popup = window.open('', 'oauth2', 'width=600,height=700');
    try {
      const url = await triggerService.oauth2Url(credentialId);
      if (popup) popup.location.href = url;
      else window.open(url, 'oauth2', 'width=600,height=700');
      // Closing the pop-up without finishing must not leave the button waiting.
      const watch = window.setInterval(() => {
        if (!popup || popup.closed) {
          window.clearInterval(watch);
          setPending(false);
        }
      }, 500);
    } catch (cause) {
      popup?.close();
      waitingFor.current = null;
      setPending(false);
      setError(errorMessage(cause, 'Sign-in could not start'));
    }
  }, []);

  return { connect, pending, error };
}
import { createHmac, randomBytes, timingSafeEqual } from 'node:crypto';
import {
  ActionNode,
  CredentialType,
  IntegrationPackage,
  NodeProperty,
  TriggerEvent,
