          this.logger.warn(
            `Could not unregister webhook ${endpointId}: ${
              error instanceof Error ? error.message : String(error)
            }`,
          );
        }
      }
      await this.repository.updateEndpoint(endpointId, {
        data: context.data,
        registered: false,
      });
    } catch (error) {
      this.logger.error(
        `Cleaning up webhook ${endpointId} failed: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
    }
