import { ExecutionRepository } from '../../domain/repositories/execution.repository';
import { WorkflowVersionForExecution } from '../../domain/models/execution.types';
import {
  ExecutionStatus,
  TriggerType,
} from '../../domain/constants/execution.constants';
import {
  buildGraphPlan,
  edgeOutput,
  GraphPlan,
  MAIN_OUTPUT,
  WorkflowDefinition,
} from '../../domain/entities/workflow-execution.entity';
import { resolveOutputs } from '@app/shared/utils/node-outputs';
import { INodeExecutor } from '../../domain/entities/node-executor';
import {
  buildNodeNameIndex,
  ItemSource,
  NodeRun,
} from '../../domain/entities/run-state';
import { Item } from '../../domain/models/item';
import { NodeCatalogPort } from '../ports/node-catalog.port';
import { NodeRunner } from './node-runner';

export interface StartRunInput {
  version: WorkflowVersionForExecution;
  triggerType: TriggerType;
  triggeredById: string | null;
  // Input of the first node: [] for a manual run, the payload for a webhook.
  triggerItems: Item[];
}

// Runs a published version node by node. Shared by the manual (synchronous)
// path and the queue processor (webhook).
export class WorkflowEngine {
  private readonly runner: NodeRunner;

  constructor(
    private readonly repository: ExecutionRepository,
    executors: INodeExecutor[],
    private readonly catalog: NodeCatalogPort,
  ) {
    this.runner = new NodeRunner(
      repository,
      new Map(executors.map((executor) => [executor.key, executor])),
    );
  }

  // Throws when the definition cannot be run, before anything is stored.
  plan(definition: unknown): GraphPlan {
    return buildGraphPlan(definition);
  }

  async createExecution(input: StartRunInput, startedAt: Date) {
    return this.repository.createExecution({
      workflowId: input.version.workflowId,
      workflowVersionId: input.version.id,
      triggerType: input.triggerType,
      triggeredById: input.triggeredById,
      startedAt,
      context:
        input.triggerType === TriggerType.MANUAL
          ? undefined
          : { triggerItems: input.triggerItems },
    });
  }

  async run(
    executionId: string,
    version: WorkflowVersionForExecution,
    triggerItems: Item[],
    startedAt: Date,
  ): Promise<ExecutionStatus> {
    // Stays FAILED if anything unexpected throws (e.g. the database), so the
    // execution is never left RUNNING.
    let finalStatus = ExecutionStatus.FAILED;
    try {
      finalStatus = await this.runNodes(executionId, version, triggerItems);
    } finally {
      const finishedAt = new Date();
      await this.repository.finishExecution(
        executionId,
        finalStatus,
        finishedAt,
        finishedAt.getTime() - startedAt.getTime(),
      );
    }
    return finalStatus;
  }

  private async runNodes(
    executionId: string,
    version: WorkflowVersionForExecution,
    triggerItems: Item[],
  ): Promise<ExecutionStatus> {
    const { order, incoming } = this.plan(version.definition);
    const definition = version.definition as WorkflowDefinition;
    const nodes = new Map(definition.nodes.map((node) => [node.id, node]));
    const names = buildNodeNameIndex(definition.nodes);
    // A malformed node without a key must fail on its own (no executor),
    // not break the catalog lookup for the whole run.
    const nodeKeys = definition.nodes
      .map((node) => node.data?.key)
      .filter((key): key is string => typeof key === 'string');
    const configSchemas = await this.catalog.getConfigSchemas([
      ...new Set(nodeKeys),
    ]);

    const runs: NodeRun[] = [];
    // Items per output of the nodes that ran; nodes that were skipped are absent.
    const produced = new Map<
      string,
      { outputs: Map<string, Item[]>; offsets: Map<string, number> }
    >();
    let status = ExecutionStatus.SUCCESS;

    for (const nodeId of order) {
      const node = nodes.get(nodeId)!;
      const configSchema = configSchemas.get(node.data?.key);

      // An edge is active when its source ran and sent items to the output it
      // leaves from; the main output of a single-output node is always active,
      // even when empty, so a filter that drops everything still lets the next
      // node run.
      let items: Item[] = triggerItems;
      const inputSources: ItemSource[] = [];
      const edges = incoming.get(nodeId) ?? [];
      if (edges.length > 0) {
        items = [];
        let activated = false;
        for (const edge of edges) {
          const upstream = produced.get(edge.source);
          const key = edgeOutput(edge);
          const sent = upstream?.outputs.get(key);
          if (!upstream || !sent) continue;
          if (key !== MAIN_OUTPUT && sent.length === 0) continue;
          const offset = upstream.offsets.get(key) ?? 0;
          sent.forEach((item, index) => {
            items.push(item);
            inputSources.push({ nodeId: edge.source, index: offset + index });
          });
          activated = true;
        }
        if (!activated) {
          const now = new Date();
          await this.repository.saveNodeLog(executionId, {
            nodeId: node.id,
            nodeKey: node.data?.key ?? 'unknown',
            status: 'SKIPPED',
            input: [],
            output: null,
            startedAt: now,
            finishedAt: now,
          });
          continue;
        }
      }

      const rawConfig =
        node.data?.config &&
        typeof node.data.config === 'object' &&
        !Array.isArray(node.data.config)
          ? (node.data.config as Record<string, unknown>)
          : {};
      const outputDefs = resolveOutputs(configSchema, rawConfig);
      const result = await this.runner.run({
        node,
        workflowId: version.workflowId,
        executionId,
        items,
        inputSources: edges.length > 0 ? inputSources : undefined,
        outputKeys: outputDefs.map((def) => def.key),
        runs,
        names,
        configSchema,
        credentialOwnerId: version.workflowOwnerId,
      });

      await this.repository.saveNodeLog(executionId, result.log);

      if (result.status === ExecutionStatus.FAILED) {
        status = ExecutionStatus.FAILED;
        break;
      }
      const offsets = new Map<string, number>();
      let offset = 0;
      for (const [key, sent] of result.outputs) {
        offsets.set(key, offset);
        offset += sent.length;
      }
      produced.set(node.id, { outputs: result.outputs, offsets });
      runs.push({
        nodeId: node.id,
        nodeName: typeof node.data.name === 'string' ? node.data.name : node.id,
        input: items,
        inputSources: edges.length > 0 ? inputSources : undefined,
        output: result.output,
      });
    }
    return status;
  }
}
import { Inject, Logger, OnApplicationBootstrap } from '@nestjs/common';
import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { ExecutionRepository } from '../../domain/repositories/execution.repository';
import { ExecutionStatus } from '../../domain/constants/execution.constants';
import { QueuedExecutionJob } from '../../application/ports/execution-queue.port';
import { WorkflowEngine } from '../../application/services/workflow-engine';
import { EXECUTION_QUEUE } from './execution-queue.module';

const DEFAULT_CONCURRENCY = 5;
const DEFAULT_STALE_MINUTES = 15;

@Processor(EXECUTION_QUEUE)
export class ExecutionProcessor
  extends WorkerHost
  implements OnApplicationBootstrap
{
  private readonly logger = new Logger(ExecutionProcessor.name);

  constructor(
    private readonly repository: ExecutionRepository,
    @Inject(WorkflowEngine) private readonly engine: WorkflowEngine,
  ) {
    super();
  }

  async onApplicationBootstrap(): Promise<void> {
    this.worker.concurrency = positiveInt(
      process.env['EXECUTION_CONCURRENCY'],
      DEFAULT_CONCURRENCY,
    );

    // Executions left RUNNING by a process that died will never finish.
    const staleMinutes = positiveInt(
      process.env['EXECUTION_STALE_MINUTES'],
      DEFAULT_STALE_MINUTES,
    );
    const failed = await this.repository.failStaleExecutions(
      new Date(Date.now() - staleMinutes * 60_000),
    );
    if (failed > 0) {
      this.logger.warn(`Marked ${failed} stale RUNNING execution(s) FAILED`);
    }
  }

  async process(job: Job<QueuedExecutionJob>): Promise<ExecutionStatus> {
    const { executionId, workflowVersionId, triggerItems } = job.data;
    const startedAt = new Date(job.data.startedAt);

    const version = await this.repository.findVersion(workflowVersionId);
    if (!version) {
      await this.repository.finishExecution(
        executionId,
        ExecutionStatus.FAILED,
        new Date(),
        Date.now() - startedAt.getTime(),
      );
      return ExecutionStatus.FAILED;
    }

    try {
      return await this.engine.run(
        executionId,
        version,
        triggerItems,
        startedAt,
      );
    } catch (error) {
      // engine.run already stored FAILED; keep the reason in the server log.
      this.logger.error(
        `Execution ${executionId} crashed: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
      return ExecutionStatus.FAILED;
    }
  }
}

function positiveInt(value: string | undefined, fallback: number): number {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : fallback;
}
import { Injectable } from '@nestjs/common';
import { BullModule, InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import {
  ExecutionQueuePort,
  QueuedExecutionJob,
} from '../../application/ports/execution-queue.port';

export const EXECUTION_QUEUE = 'executions';

// Connection is read at startup (after .env is loaded), not at import time.
export const executionQueueImports = [
  BullModule.forRootAsync({
    useFactory: () => ({
      // Separate key space per environment, e.g. so e2e runs are not picked
      // up by a dev server sharing the same Redis.
      prefix: process.env['BULLMQ_PREFIX'] || 'bull',
      connection: {
        host: process.env['REDIS_HOST'] || 'localhost',
        port: parseInt(process.env['REDIS_PORT'] || '6379', 10),
        password: <REDACTED>'REDIS_PASSWORD'] || undefined,
      },
    }),
  }),
  BullModule.registerQueue({
    name: EXECUTION_QUEUE,
    defaultJobOptions: {
      // A failed run is never replayed automatically: nodes may already have
      // sent emails or messages.
      attempts: 1,
      removeOnComplete: 1000,
      removeOnFail: 1000,
    },
  }),
];

@Injectable()
export class BullMqExecutionQueue implements ExecutionQueuePort {
  constructor(@InjectQueue(EXECUTION_QUEUE) private readonly queue: Queue) {}

  async enqueue(job: QueuedExecutionJob): Promise<void> {
    await this.queue.add('run', job, { jobId: job.executionId });
  }
}
import { Item } from '../../../domain/models/item';

// Starts a run in the background (webhook). Returns the execution id at once;
// the queue processor runs the nodes.
export class EnqueueExecutionCommand {
  constructor(
    readonly workflowVersionId: string,
    readonly triggerItems: Item[],
  ) {}
}

import { Inject, Injectable, NotFoundException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { ExecutionRepository } from '../../../domain/repositories/execution.repository';
import { TriggerType } from '../../../domain/constants/execution.constants';
import { ExecutionQueuePort } from '../../ports/execution-queue.port';
import { WorkflowEngine } from '../../services/workflow-engine';

@Injectable()
@CommandHandler(EnqueueExecutionCommand)
export class EnqueueExecutionHandler implements ICommandHandler<EnqueueExecutionCommand> {
  constructor(
    private readonly repository: ExecutionRepository,
    @Inject(WorkflowEngine) private readonly engine: WorkflowEngine,
    private readonly queue: ExecutionQueuePort,
  ) {}

  async execute(command: EnqueueExecutionCommand): Promise<string> {
    const version = await this.repository.findVersion(
      command.workflowVersionId,
    );
    if (!version) throw new NotFoundException('Workflow version not found');

    const startedAt = new Date();
    const executionId = await this.engine.createExecution(
      {
        version,
        triggerType: TriggerType.WEBHOOK,
        triggeredById: null,
        triggerItems: command.triggerItems,
      },
      startedAt,
    );
    await this.queue.enqueue({
      executionId,
      workflowVersionId: version.id,
      triggerItems: command.triggerItems,
      startedAt: startedAt.toISOString(),
    });
    return executionId;
  }
}

