import {
  ActionNode,
  AppApiError,
  nodeParameters,
  PackageRegistry,
} from '@app/apps';
import {
  INodeExecutor,
  IPerItemExecutor,
} from '../../domain/entities/node-executor';
import { PassThroughTriggerExecutor } from './pass-through-trigger-executor';
import { PackageActionLimits } from '../../domain/constants/execution.constants';
import { Item, ItemJson } from '../../domain/models/item';
import { Sleep } from './llm-generate-executor';

type Parameters = Record<string, unknown>;

const defaultSleep: Sleep = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

// Runs an action node of an integration package for each item: the engine
// resolves expressions and the credential, the package talks to the app.
export class PackageActionExecutor implements IPerItemExecutor<Parameters> {
  readonly runMode = 'per_item' as const;
  readonly key: string;

  constructor(
    private readonly node: ActionNode,
    private readonly sleep: Sleep = defaultSleep,
  ) {
    this.key = node.key;
  }

  // Required fields must not resolve to blank (e.g. an expression whose
  // field is missing in the item).
  parseConfig(raw: unknown): Parameters {
    const parameters = nodeParameters(raw);
    for (const property of this.node.properties) {
      if (!property.required) continue;
      const value = parameters[property.name];
      if (
        value === undefined ||
        value === null ||
        (typeof value === 'string' && value.trim() === '')
      ) {
        throw new Error(`${property.displayName} is required`);
      }
    }
    return parameters;
  }

  expectedConnectorKey(rawConfig: Record<string, unknown>): string | null {
    if (this.node.credentialType) return this.node.credentialType;
    const from = this.node.credentialTypeFrom;
    const chosen = from ? rawConfig[from.field] : undefined;
    return from && typeof chosen === 'string' && from.types.includes(chosen)
      ? chosen
      : null;
  }

  async executeItem(params: {
    config: Parameters;
    item: Item;
    credential: unknown;
  }): Promise<ItemJson | ItemJson[] | null> {
    const credential =
      params.credential && typeof params.credential === 'object'
        ? (params.credential as Record<string, unknown>)
        : null;
    if (this.node.credentialType && !credential) {
      throw new Error('Choose a credential for this node');
    }
    return this.withRetry(() =>
      this.node.execute({
        parameters: params.config,
        credential,
        item: { json: params.item.json },
      }),
    );
  }

  // Rate limits and outages are retried with a growing pause; anything else
  // (e.g. Messenger's 24-hour window, revoked access) fails at once.
  private async withRetry<T>(attempt: () => Promise<T>): Promise<T> {
    for (let retry = 0; ; retry += 1) {
      try {
        return await attempt();
      } catch (error) {
        const retryable = error instanceof AppApiError && error.retryable;
        if (!retryable || retry >= PackageActionLimits.MAX_RETRIES) throw error;
        await this.sleep(1000 * 2 ** retry);
      }
    }
  }
}

// Executors of every package node: a trigger passes its event on (the event
// is the run's input), an action runs per item.
export function packageExecutors(registry: PackageRegistry): INodeExecutor[] {
  return registry
    .allNodes()
    .map((node) =>
      node.kind === 'action'
        ? new PackageActionExecutor(node)
        : new PassThroughTriggerExecutor(node.key),
    );
}
import { createHash } from 'node:crypto';
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import Redis from 'ioredis';
import {
  ChatMemoryPort,
  ChatMessage,
} from '../../application/ports/chat-memory.port';

// One Redis list per workflow and session. The session key (a customer id) is
// hashed, so it never shows up in Redis; the prefix keeps e2e runs and dev
// servers that share a Redis apart, like BULLMQ_PREFIX does for the queue.
@Injectable()
export class RedisChatMemory implements ChatMemoryPort, OnModuleDestroy {
  private readonly redis = new Redis({
    host: process.env['REDIS_HOST'] || 'localhost',
    port: parseInt(process.env['REDIS_PORT'] || '6379', 10),
    password: <REDACTED>'REDIS_PASSWORD'] || undefined,
    lazyConnect: true,
    maxRetriesPerRequest: 3,
  });

  private key(workflowId: string, sessionKey: string): string {
    const prefix = process.env['BULLMQ_PREFIX'] || 'flowpilot';
    const session = createHash('sha256').update(sessionKey).digest('hex');
    return `${prefix}:chatmem:${workflowId}:${session}`;
  }

  async load(
    workflowId: string,
    sessionKey: string,
    limit: number,
  ): Promise<ChatMessage[]> {
    const rows = await this.redis.lrange(
      this.key(workflowId, sessionKey),
      -limit,
      -1,
    );
    return rows.flatMap((row) => {
      try {
        const message = JSON.parse(row) as Partial<ChatMessage>;
        return (message.role === 'user' || message.role === 'assistant') &&
          typeof message.content === 'string'
          ? [{ role: message.role, content: message.content }]
          : [];
      } catch {
        return [];
      }
    });
  }

  async append(
    workflowId: string,
    sessionKey: string,
    messages: ChatMessage[],
    options: { maxMessages: number; ttlSeconds: number },
  ): Promise<void> {
    if (messages.length === 0) return;
    const key = this.key(workflowId, sessionKey);
    await this.redis
      .multi()
      .rpush(key, ...messages.map((message) => JSON.stringify(message)))
      .ltrim(key, -options.maxMessages, -1)
      .expire(key, options.ttlSeconds)
      .exec();
  }

  async clear(workflowId: string, sessionKey: string): Promise<void> {
    await this.redis.del(this.key(workflowId, sessionKey));
  }

  async onModuleDestroy(): Promise<void> {
    await this.redis.quit().catch(() => undefined);
  }
}
import { z } from 'zod';
import {
  ExecutionContext,
  IPerItemExecutor,
} from '../../domain/entities/node-executor';
import { NodeKeys } from '../../domain/constants/execution.constants';
import { Item, ItemJson } from '../../domain/models/item';
import { ChatMemoryPort, ChatMessage } from '../ports/chat-memory.port';

// A session keeps at most this many messages (25 question-and-answer turns).
export const MAX_SESSION_MESSAGES = 50;
const MAX_TURNS_LOADED = MAX_SESSION_MESSAGES / 2;
const SECONDS_PER_DAY = 24 * 60 * 60;

// An expression can resolve to a number or an object; memory works on text.
const asText = (value: unknown): unknown => {
  if (value === null || value === undefined) return '';
  return typeof value === 'string' ? value : JSON.stringify(value);
};

const ConfigSchema = z.object({
  mode: z.enum(['load', 'save', 'clear']).default('load'),
  session_key: z.preprocess(
    asText,
    z.string().trim().min(1, 'Chat Memory needs a session key'),
  ),
  // load: how many question-and-answer turns to read back.
  window: z.coerce.number().int().min(1).max(MAX_TURNS_LOADED).default(10),
  // save: both are stored; a blank one is left out.
  user_message: z.preprocess(asText, z.string().default('')),
  assistant_message: z.preprocess(asText, z.string().default('')),
  ttl_days: z.coerce.number().int().min(1).max(90).default(7),
});

export type ChatMemoryConfig = z.infer<typeof ConfigSchema>;

const SPEAKER: Record<ChatMessage['role'], string> = {
  user: 'Khách',
  assistant: 'Bot',
};

// Reads and writes the recent messages of one conversation, so an LLM node can
// be given what was said before. The item passes through unchanged, except
// that "load" adds `history` and `history_text` to it.
export class ChatMemoryExecutor implements IPerItemExecutor<ChatMemoryConfig> {
  readonly key = NodeKeys.MEMORY_CHAT;
  readonly runMode = 'per_item' as const;

  constructor(private readonly memory: ChatMemoryPort) {}

  parseConfig(raw: unknown): ChatMemoryConfig {
    return ConfigSchema.parse(raw);
  }

  async executeItem(params: {
    config: ChatMemoryConfig;
    item: Item;
    credential: unknown;
    context?: ExecutionContext;
  }): Promise<ItemJson> {
    const { config, item, context } = params;
    if (!context) throw new Error('Chat Memory needs a workflow to run in');
    const { workflowId } = context;
    const session = config.session_key;

    if (config.mode === 'clear') {
      await this.memory.clear(workflowId, session);
      return item.json;
    }

    if (config.mode === 'save') {
      const messages: ChatMessage[] = [];
      if (config.user_message.trim()) {
        messages.push({ role: 'user', content: config.user_message });
      }
      if (config.assistant_message.trim()) {
        messages.push({ role: 'assistant', content: config.assistant_message });
      }
      await this.memory.append(workflowId, session, messages, {
        maxMessages: MAX_SESSION_MESSAGES,
        ttlSeconds: config.ttl_days * SECONDS_PER_DAY,
      });
      return item.json;
    }

    const history = await this.memory.load(
      workflowId,
      session,
      config.window * 2,
    );
    return {
      ...item.json,
      history,
      history_text: history
        .map((message) => `${SPEAKER[message.role]}: ${message.content}`)
        .join('\n'),
    };
  }
}

