import { useCallback, useEffect, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { errorMessage, triggerService } from '../services/trigger.service';
import type {
  ActivationState,
  NodeOption,
  NodeWebhook,
  TestListen,
} from '../types/trigger.types';

export const triggerKeys = {
  activation: (workflowId: string) => ['workflow-activation', workflowId] as const,
  webhooks: (workflowId: string) => ['workflow-webhooks', workflowId] as const,
  options: (nodeKey: string, property: string, credentialId: string | undefined) =>
    ['node-options', nodeKey, property, credentialId ?? ''] as const,
};

export function useActivation(workflowId: string | undefined) {
  return useQuery<ActivationState>({
    queryKey: triggerKeys.activation(workflowId ?? ''),
    queryFn: () => triggerService.activation(workflowId as string),
    enabled: !!workflowId,
  });
}

export function useSetActive(workflowId: string) {
  const queryClient = useQueryClient();
  return useMutation<ActivationState, Error, boolean>({
    mutationFn: (active) => triggerService.setActive(workflowId, active),
    onSuccess: (state) => {
      queryClient.setQueryData(triggerKeys.activation(workflowId), state);
    },
  });
}

// URLs of the draft's trigger nodes. With `waitForNodeId` the query checks
// again until that node has a URL (a new node appears once the draft saves).
export function useNodeWebhooks(workflowId: string | undefined, waitForNodeId?: string) {
  return useQuery<NodeWebhook[]>({
    queryKey: triggerKeys.webhooks(workflowId ?? ''),
    queryFn: () => triggerService.webhooks(workflowId as string),
    enabled: !!workflowId,
    refetchInterval: (query) =>
      waitForNodeId && !triggerService.findForNode(query.state.data, waitForNodeId)?.url
        ? 2000
        : false,
  });
}

export function useNodeOptions(
  nodeKey: string,
  property: string,
  credentialId: string | undefined,
  needsCredential: boolean,
) {
  return useQuery<NodeOption[], Error>({
    queryKey: triggerKeys.options(nodeKey, property, credentialId),
    queryFn: async () => {
      try {
        return await triggerService.loadOptions(nodeKey, property, credentialId);
      } catch (error) {
        throw new Error(errorMessage(error, 'Options could not be loaded'), { cause: error });
      }
    },
    enabled: !needsCredential || !!credentialId,
    retry: false,
  });
}

const POLL_MS = 2000;

// "Listen for test event": starts a listen, polls until an event arrives or
// it expires, and stops it when the panel goes away.
export function useTestListen(workflowId: string, nodeId: string) {
  const [listen, setListen] = useState<TestListen | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [starting, setStarting] = useState(false);
  const active = useRef<string | null>(null);

  useEffect(() => {
    if (!listen || listen.status !== 'waiting') return;
    const timer = window.setInterval(() => {
      triggerService
        .testListen(listen.listenId)
        .then((next) => {
          if (active.current === next.listenId) setListen(next);
        })
        .catch(() => undefined);
    }, POLL_MS);
    return () => window.clearInterval(timer);
  }, [listen]);

  // Leaving the node (or the page) stops a listen still waiting.
  useEffect(
    () => () => {
      if (active.current) void triggerService.stopTestListen(active.current).catch(() => undefined);
    },
    [workflowId, nodeId],
  );

  const start = useCallback(async () => {
    setError(null);
    setStarting(true);
    try {
      const started = await triggerService.startTestListen(workflowId, nodeId);
      active.current = started.listenId;
      setListen(started);
    } catch (cause) {
      setError(errorMessage(cause, 'Could not start listening'));
    } finally {
      setStarting(false);
    }
  }, [workflowId, nodeId]);

  const stop = useCallback(async () => {
    const listenId = active.current;
    active.current = null;
    setListen(null);
    if (listenId) await triggerService.stopTestListen(listenId).catch(() => undefined);
  }, []);

  return { listen, error, starting, start, stop };
}
import { AlertCircle } from 'lucide-react';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { useActivation, useSetActive } from '../hooks/useWorkflowTriggers';

interface ActiveToggleProps {
  workflowId: string;
}

// The workflow's Active switch: on, its published version listens for events
// (webhooks are registered with the apps); off, nothing listens.
export function ActiveToggle({ workflowId }: ActiveToggleProps) {
  const { data: state, isLoading } = useActivation(workflowId);
  const setActive = useSetActive(workflowId);
  const active = state?.active ?? false;

  return (
    <div className="flex items-center gap-2">
      {setActive.isError && (
        <span
          role="alert"
          title={setActive.error.message}
          className="flex max-w-xs items-center gap-1 truncate text-xs text-destructive"
        >
          <AlertCircle className="size-3.5 shrink-0" />
          <span className="truncate">{setActive.error.message}</span>
        </span>
      )}
      {setActive.isPending && (
        <span className="text-xs text-muted-foreground">
          {active ? 'Turning off…' : 'Registering webhooks…'}
        </span>
      )}
      <Label
        htmlFor="workflow-active"
        className={active ? 'text-xs text-emerald-700' : 'text-xs text-muted-foreground'}
      >
        Active
      </Label>
      <Switch
        id="workflow-active"
        checked={active}
        disabled={isLoading || setActive.isPending}
        onCheckedChange={(checked) => setActive.mutate(checked)}
      />
    </div>
  );
}
import { useEffect, useState } from 'react';
import { Loader2, Radio, Square } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useTestListen } from '../hooks/useWorkflowTriggers';

interface TestEventPanelProps {
  workflowId: string;
  nodeId: string;
  // The draft has unsaved changes the server would not see yet.
  draftSaving: boolean;
}

// "Listen for test event": waits for one real event with the node's draft
// settings and shows what arrived, so later nodes can be written against it.
export function TestEventPanel({ workflowId, nodeId, draftSaving }: TestEventPanelProps) {
  const { listen, error, starting, start, stop } = useTestListen(workflowId, nodeId);
  const secondsLeft = useSecondsLeft(listen?.status === 'waiting' ? listen.expiresAt : null);

  return (
    <section className="space-y-2 rounded-lg border border-dashed border-border p-3">
      <div className="flex items-center justify-between gap-2">
        <p className="text-xs font-medium">Test event</p>
        {listen?.status === 'waiting' ? (
          <Button type="button" size="sm" variant="outline" onClick={() => void stop()}>
            <Square className="size-3.5" />
            Stop
          </Button>
        ) : (
          <Button
            type="button"
            size="sm"
            onClick={() => void start()}
            disabled={starting || draftSaving}
          >
            {starting ? <Loader2 className="size-3.5 animate-spin" /> : <Radio className="size-3.5" />}
            Listen for test event
          </Button>
        )}
      </div>

      {listen?.status === 'waiting' && (
        <p className="text-xs text-muted-foreground">
          Waiting for an event… ({formatSeconds(secondsLeft)}). Send one now (e.g. message the
          Page). It will not run the workflow.
        </p>
      )}
      {listen?.status === 'expired' && (
        <p className="text-xs text-muted-foreground">No event received in time. Try again.</p>
      )}
      {error && <p className="text-xs text-destructive">{error}</p>}
      {listen?.status === 'received' && listen.event && (
        <div className="space-y-1">
          <p className="text-xs text-emerald-700">Event received. Use its fields in later nodes.</p>
          <pre className="max-h-64 overflow-auto rounded bg-muted p-2 font-mono text-[11px] leading-snug">
            {JSON.stringify(listen.event, null, 2)}
          </pre>
        </div>
      )}
    </section>
  );
}

function useSecondsLeft(expiresAt: string | null): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!expiresAt) return;
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, [expiresAt]);
  return expiresAt ? Math.max(0, Math.round((new Date(expiresAt).getTime() - now) / 1000)) : 0;
}

function formatSeconds(total: number): string {
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
}

