import { ExecutionStatus } from '../constants/execution.constants';
import {
  WorkflowVersionForExecution,
  ExecutionRecord,
  NodeLogRecord,
  ResolvedCredential,
} from '../models/execution.types';

export abstract class ExecutionRepository {
  abstract findVersion(id: string): Promise<WorkflowVersionForExecution | null>;
  abstract createExecution(input: Omit<ExecutionRecord, 'id'>): Promise<string>;
  abstract resolveCredential(
    credentialId: string,
    ownerId: string,
  ): Promise<ResolvedCredential>;
  abstract saveNodeLog(executionId: string, log: NodeLogRecord): Promise<void>;
  abstract finishExecution(
    id: string,
    status: ExecutionStatus,
    finishedAt: Date,
    durationMs: number,
  ): Promise<void>;
  abstract findExecutionResult(id: string): Promise<unknown>;
  // Marks executions still RUNNING since before the cutoff as FAILED
  // (their process died); returns how many were changed.
  abstract failStaleExecutions(startedBefore: Date): Promise<number>;
}
import { ExecutionStatus, TriggerType } from '../constants/execution.constants';

export interface WorkflowVersionForExecution {
  id: string;
  workflowId: string;
  definition: unknown;
  workflowOwnerId: string;
}

export interface ExecutionRecord {
  id: string;
  workflowId: string;
  workflowVersionId: string;
  triggerType: TriggerType;
  // null when nobody pressed Run (webhook).
  triggeredById: string | null;
  startedAt: Date;
  // Normalized trigger payload, kept for debugging.
  context?: unknown;
}

export interface NodeLogRecord {
  nodeId: string;
  nodeKey: string;
  // SKIPPED: no incoming edge was activated, so the node did not run.
  status: ExecutionStatus | 'SKIPPED';
  input: unknown;
  output: unknown;
  errorMessage?: string;
  startedAt: Date;
  finishedAt: Date;
}

export interface ResolvedCredential {
  connectorKey: string;
  secret: <REDACTED>;
}
import { Item } from '../../domain/models/item';

export interface QueuedExecutionJob {
  executionId: string;
  workflowVersionId: string;
  triggerItems: Item[];
  startedAt: string; // ISO time the execution row was created
}

export abstract class ExecutionQueuePort {
  abstract enqueue(job: QueuedExecutionJob): Promise<void>;
}
